function renderRubyShop(){const box=$('ruby-upgrades');box.replaceChildren();$('ruby-shop-balance').textContent=`You have ${fmt(game.state.rubies)} rubies.`;for(const key of Object.keys(RUBY_UPGRADES)){const u=game.rubyUpgradeInfo(key),row=document.createElement('div');row.className='upgrade';const copy=document.createElement('div'),heading=document.createElement('h3'),desc=document.createElement('p'),progress=document.createElement('div');heading.textContent=u.name;desc.textContent=u.description;progress.className='small muted';progress.textContent=`Level ${u.level} / ${u.max}`;copy.append(heading,desc,progress);const button=document.createElement('button');button.textContent=u.level>=u.max?'Max':`${fmt(u.cost)} 💎`;button.disabled=u.level>=u.max||game.state.rubies<u.cost;button.onclick=()=>{if(game.buyRubyUpgrade(key)){save();render();renderRubyShop();notice(`${u.name} upgraded.`,'success');}};row.append(copy,button);box.append(row);}}
