 const description=document.createElement('p');if(q){const xp=game.experienceFor(q.family,q.tier);description.className='quest-order';const label=document.createElement('span'),name=document.createElement('strong'),level=document.createElement('span');label.className='small muted';label.textContent='Required potion';name.textContent=FAMILIES[q.family].recipes[q.tier].name;level.textContent=`Level ${q.level+1} or higher · ${xp}${game.experienceIsEstimated(q.family,q.tier)?' estimated':''} EXP`;description.append(label,name,level);}
