 const timer=document.createElement('p');timer.dataset.questTimer=i;timer.className=state.phase==='active'?'timer quest-deadline':'timer';
 const actions=document.createElement('div');actions.className='quest-actions';
 function button(label,action,disabled=false){const b=document.createElement('button');b.textContent=label;b.disabled=disabled;if(label==='Accept quest'||label==='Give potion')b.className='primary';b.onclick=()=>{if(action()){save();render();updateBeltLabels();}};actions.append(b);}
