function visitorRewardText(t,state){if(t.rewardType==='fairy'){const f=FAIRIES.find(f=>f.id===state.rewardFairyId);return f?f.name+' ×1':'1 random fairy';}return `${t.reward} ${t.powerup==='protection'?'protection':t.powerup==='enhancement'?'enhancement bonus':'sell bonus'} charges`;}
