function renderFairies(){const counts=game.state.fairies,total=Object.values(counts).reduce((a,b)=>a+b,0),active=game.state.activeFairyId;$('fairy-summary').textContent=`${Object.keys(counts).length} / ${FAIRIES.length} fairy types · ${fmt(total)} received · ${active?FAIRIES.find(f=>f.id===active).name+' is active':'No fairy equipped'}`;
 const grid=$('fairy-grid');grid.replaceChildren();for(const f of FAIRIES){const count=counts[f.id]||0,level=game.fairyLevel(f.id),card=document.createElement('div');card.className='fairy-card '+(count?'owned':'locked')+(active===f.id?' equipped':'');const im=document.createElement('img');im.src=art(f.image);im.alt=f.name;const title=document.createElement('h3');title.textContent=f.name;const label=document.createElement('p');label.textContent=count?`Lv ${level} / 10 · received ×${fmt(count)}`:'Not collected yet';const effect=document.createElement('p');effect.textContent=FAIRY_LABELS[f.id]||'No matching mechanic in this prototype yet';card.append(im,title,label,effect);if(count&&FAIRY_LABELS[f.id]){const button=document.createElement('button');button.textContent=active===f.id?'Unequip':'Equip';button.onclick=()=>{game.setActiveFairy(active===f.id?null:f.id);save();renderFairies();render();updateBeltLabels();};card.append(button);}grid.append(card);}}
function questTimerText(t){const now=Date.now();return t.phase==='active'?`Time left: ${Math.max(0,Math.ceil((t.deadline-now)/1000))}s`:t.phase==='returning'?`Reward arrives in ${Math.max(0,Math.ceil((t.readyAt-now)/1000))}s`:'';}

