function imgButton(family,tier){const f=FAMILIES[family],m=f.materials[tier],b=document.createElement('button');b.className='ingredient';b.title=`${m.name} · +${m.value} value`;const img=document.createElement('img');img.src=art(m.image);img.alt=m.name;b.append(img);return b;}
