 for(const m of conveyor.items){let el=beltElements.get(m.id);if(!el){el=m.kind==='ticket'?ticketButton():imgButton(m.family,m.tier);el.tabIndex=-1;el.setAttribute('aria-hidden','true');el.dataset.belt=m.id;el.onclick=()=>catchMaterial(m.id);beltElements.set(m.id,el);$('ingredients').append(el);}const x=reducedMotion?Math.round(m.x/conveyor.spacing)*conveyor.spacing:m.x;el.style.transform=`translateX(${x}px)`;}
