$('ingredient-mode-toggle').onclick=()=>{ingredientMode=ingredientMode==='conveyor'?'manual':'conveyor';$('ingredient-mode-toggle').textContent=ingredientMode==='conveyor'?'Choose exact ingredients':'Use conveyor';startBelt(false);};
new ResizeObserver(entries=>{beltWidth=entries[0].contentRect.width;}).observe($('ingredients'));
function collectMaterial(family,tier,id=null){const starting=!game.state.potion;if(!game.collect(family,tier))return;if(id!==null)conveyor.take(id);notice(starting?`${game.recipe().name} started.`:`${FAMILIES[family].materials[tier].name} added to the brew.`);save();render();updateBeltLabels();if(ingredientMode==='conveyor')syncBelt();else drawSelectedIngredients();}
