function animate(now){const delta=Math.max(0,now-lastFrame);lastFrame=now;if(conveyor&&ingredientMode==='conveyor'){conveyor.tiers=game.state.tiers;conveyor.advance(delta,!!game.state.potion,game.state.speed,beltWidth);syncBelt();}requestAnimationFrame(animate);}

$('enhance').onclick=()=>{const previousAchievements=masteredPotionCount(),result=game.enhance();if(!result)return;notice(result==='success'?'Enhancement succeeded. Keep brewing—or sell while you’re ahead.':result==='protected'?'Enhancement failed, but a protection charge saved the potion.':result==='fairy-protected'?'Your fairy protected the potion from a failed enhancement.':'The potion was lost. Start a fresh brew with any ingredient.',result==='success'?'success':result==='protected'?'':'failure');if(masteredPotionCount()>previousAchievements&&game.state.potion){const p=game.state.potion;notice(ACHIEVEMENT_LORE.entries[p.family+'-'+p.tier].title+' unlocked!','success');}flash(result);save();render();if(!game.state.potion)updateBeltLabels();};
$('sell').onclick=()=>{const doubled=game.state.powerups.selling>0,value=game.sell();if(value===null)return;notice(`Sold for ${fmt(value)} coins${doubled?' with a ×2 sell bonus':''}.`,'success');save();render();updateBeltLabels();};
