document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||e.altKey||e.metaKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.repeat)return;if(/^[1-6]$/.test(e.key)){const i=Number(e.key)-1;if(ingredientMode==='manual'&&i<3)collectMaterial(i,Math.min(game.state.selected[i],game.state.tiers[i]));else if(belt[i])catchMaterial(belt[i].id);}if(e.key.toLowerCase()==='e')$('enhance').click();if(e.key.toLowerCase()==='s')$('sell').click();});
const music=art('Main_Theme.ogg')?new Audio(art('Main_Theme.ogg')):null;if(music){music.loop=true;music.volume=.25;}$('music').onclick=async()=>{if(!music){notice('The theme is not included in this build.');return;}if(music.paused){try{await music.play();$('music').textContent='Music on';$('music').classList.add('music-active');}catch(e){notice('The browser could not play the theme.');}}else{music.pause();$('music').textContent='Music off';$('music').classList.remove('music-active');}};
$('dev-coins').onclick=()=>{game.state.coins=Math.min(1e300,game.state.coins+10000);save();render();notice('Debug cheat: added 10,000 coins.','success');};
$('dev-unlock').onclick=()=>{game.state.tiers=[24,24,24];game.state.selected=[24,24,24];save();render();startBelt();notice('Debug cheat: all material tiers unlocked.','success');};
$('dev-max-potion').onclick=()=>{const p=game.state.potion;if(!p){notice('Start a potion first.');return;}const r=game.recipe(),fromLevel=p.level,gained=Math.max(0,r.max_level-1-fromLevel),fairyBonus=game.fairyEffects().enhancementMultiplier?.[p.family]||0;for(let level=fromLevel;level<r.max_level-1;level++){const multiplier=r.multipliers[level];if(Number.isFinite(multiplier))p.value=Math.min(1e300,p.value*multiplier*(1+fairyBonus));}p.level=r.max_level-1;const record=game.statRecipe();record.highestLevel=r.max_level;record.enhancements+=gained;game.state.metrics.enhancementsSucceeded=Math.min(1e300,game.state.metrics.enhancementsSucceeded+gained);game.state.metrics.enhancementAttempts=Math.min(1e300,game.state.metrics.enhancementAttempts+gained);save();render();notice('Debug cheat: current potion set to maximum level and value.','success');};
$('export').onclick=async()=>{try{save(true);$('save-code').value=await makeSaveCode(saveBlocked&&stored.raw?stored.raw:game.state);$('save-message').textContent='Compressed save code generated. Copy it somewhere safe.';}catch(error){$('save-message').textContent='Could not create save code: '+error.message;}};$('copy-save-code').onclick=async()=>{const field=$('save-code');if(!field.value){$('save-message').textContent='Generate a save code first.';return;}try{await navigator.clipboard.writeText(field.value);$('save-message').textContent='Save code copied.';}catch{field.focus();field.select();$('save-message').textContent='Save code selected. Press Ctrl+C to copy it.';}};$('import').onclick=async()=>{try{const next=await readSaveCode($('save-code').value.trim());if(!confirm('Replace your current shop with this save code?'))return;saveBlocked=false;game=new PotionGame(next);game.tick();save(true);travelerSnapshot='';render();startBelt();notice('Your saved shop is ready.','success');$('save-message').textContent='Save code imported.';}catch(error){$('save-message').textContent='Could not import: '+error.message;}};
$('reset').onclick=()=>{if(!confirm('Start a new shop? Export a backup first if you want to keep your progress.'))return;saveBlocked=false;game=new PotionGame();game.tick();save(true);travelerSnapshot='';render();startBelt();notice('A fresh start. Catch a passing ingredient.');$('save-message').textContent='New shop started.';};
let lastTrackedAt=performance.now(),lastStatisticsSave=performance.now(),lastDisplayedSecond=-1;
setInterval(()=>{const tickNow=performance.now(),elapsed=tickNow-lastTrackedAt;lastTrackedAt=tickNow;if(!document.hidden&&elapsed<2000)game.recordPlayTime(elapsed);if(tickNow-lastStatisticsSave>=300000){lastStatisticsSave=tickNow;save(true);}const events=game.tick();if(events.length){notice(events.map(e=>e.kind==='arrived'?`${e.traveler.name} has arrived with an order.`:e.kind==='failed'?`${e.traveler.name}'s quest expired.`:e.kind==='request'?`${e.traveler.name} completed ${e.request.name}.${e.fairyId?' '+FAIRIES.find(f=>f.id===e.fairyId).name+' joined your collection.':''}`:rewardArrivalText(e.traveler)).join(' '),events.some(e=>e.kind==='failed')?'failure':'success');save();render();if($('fairy-dialog').open)renderFairies();if($('ruby-shop-dialog').open)renderRubyShop();if($('fairy-draw-dialog').open)renderFairyDraw();if($('request-dialog').open)renderRequestBoard();}
 const second=Math.floor(Date.now()/1000);if(second!==lastDisplayedSecond){lastDisplayedSecond=second;document.querySelectorAll('[data-quest-timer]').forEach(el=>{const t=game.state.travelers[Number(el.dataset.questTimer)];if(['active','returning'].includes(t.phase))setText(el,questTimerText(t));});updateQuestButtons();if(game.state.request){setText($('request-current'),requestStatusText());if($('request-dialog').open)setText($('request-status'),requestStatusText());}if($('statistics-dialog').open){if(statisticsDirty)renderStatistics();setText($('statistics-play-time'),duration(game.state.metrics.activePlayMs));}}
},250);
window.addEventListener('pagehide',()=>save(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)save(true);});game.tick();render();startBelt();requestAnimationFrame(animate);if(saveOK)save(true);

document.addEventListener('click',event=>{const current=event.target.closest('.header-menu');document.querySelectorAll('.header-menu[open]').forEach(menu=>{if(menu!==current||event.target.closest('button'))menu.open=false;});});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.header-menu[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary').focus();});});
